INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es immer besser, Konflikte sofort anzusprechen?', 2, '[{"text": "Nein", "correct": true, "because": "Manchmal hilft Abwarten zur Deeskalation"}, {"text": "Ja", "correct": false, "because": "Timing kann entscheidend sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Spannungen zwischen zwei Kollegen zu lösen?', 3, '[{"text": "Moderiertes Gespräch", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schriftliche Berichte", "correct": false, "because": "Wenig interaktiv"}, {"text": "Ignorieren", "correct": false, "because": "Verschärft das Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren helfen mir, Streit in einem Team zu entschärfen?', 5, '[{"text": "Klarheit in der Kommunikation", "correct": true, "because": "Missverständnisse reduzieren"}, {"text": "Neutrale Moderation", "correct": true, "because": "Objektivität gewährleisten"}, {"text": "Strenge Regeln", "correct": false, "because": "Kann Spannungen erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Emotionen sollten ignoriert werden. b) Aktives Zuhören hilft.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Emotionen beeinflussen Lösungen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich zwischen zwei Parteien vermittle?', 4, '[{"text": "Eigene Meinung", "correct": true, "because": "Neutralität ist entscheidend"}, {"text": "Faktenlage", "correct": false, "because": "Basis der Lösung"}, {"text": "Emotionen", "correct": false, "because": "Wichtig für Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein neutraler Dritter immer nötig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Selbstlösung oft möglich"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik nutze ich, um Missverständnisse zu klären?', 3, '[{"text": "Rückfragen stellen", "correct": true, "because": "Bestätigt Verständnis"}, {"text": "Schweigen", "correct": false, "because": "Kann Spannung erhöhen"}, {"text": "Direkte Anweisungen", "correct": false, "because": "Einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze fördern eine konstruktive Diskussion?', 5, '[{"text": "Faktenbasierte Argumente", "correct": true, "because": "Objektivität stärken"}, {"text": "Gemeinsame Ziele betonen", "correct": true, "because": "Zusammenarbeit fördern"}, {"text": "Schuldzuweisungen", "correct": false, "because": "Verschärft Konflikte"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Konflikte schaden immer. b) Mediation ist die einzige Lösung. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Konflikte können nützlich sein, Mediation eine Option"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Spannungen zu lösen?', 4, '[{"text": "Verständnis für Positionen", "correct": false, "because": "Basis für Lösung"}, {"text": "Klare Kommunikation", "correct": false, "because": "Vermeidet Missverständnisse"}, {"text": "Persönliche Vorurteile", "correct": true, "because": "Stört Neutralität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Konflikte immer negativ?', 2, '[{"text": "Nein", "correct": true, "because": "Können Verbesserungen fördern"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig schädlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte unterstützten eine Klärung zwischen Teams?', 4, '[{"text": "Gemeinsames Treffen", "correct": true, "because": "Direkter Austausch"}, {"text": "Regeln festlegen", "correct": true, "because": "Struktur schaffen"}, {"text": "Schriftliche Beschwerden", "correct": false, "because": "Wenig dialogisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schweigen Konflikte löst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation ist nötig"}, {"text": "Ja", "correct": false, "because": "Kann Missverständnisse verstärken"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Streit schlichte?', 3, '[{"text": "Neutralität", "correct": true, "because": "Vertrauen schaffen"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Dominanz", "correct": false, "because": "Verschärft Spannungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zuhören ist wichtiger als Reden. b) Emotionen stören immer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Emotionen können hilfreich sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine offene Diskussion?', 5, '[{"text": "Klarheit schaffen", "correct": true, "because": "Missverständnisse klären"}, {"text": "Vertrauen stärken", "correct": true, "because": "Transparenz fördern"}, {"text": "Schnellschüsse", "correct": false, "because": "Oberflächlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Klärung unwichtig?', 3, '[{"text": "Faktenbasis", "correct": false, "because": "Fundament der Lösung"}, {"text": "Empathie", "correct": false, "because": "Verständnis fördern"}, {"text": "Persönliche Angriffe", "correct": true, "because": "Verschlimmert Streit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Reicht es, nur eine Seite anzuhören?', 3, '[{"text": "Nein", "correct": true, "because": "Beide Perspektiven nötig"}, {"text": "Ja", "correct": false, "because": "Einseitigkeit unfair"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Moderator immer neutral sein muss?', 2, '[{"text": "Ja", "correct": true, "because": "Vertrauen sichern"}, {"text": "Nein", "correct": false, "because": "Parteilichkeit stört"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Haltung wähle ich, um Spannungen zu reduzieren?', 4, '[{"text": "Offenheit", "correct": true, "because": "Dialog fördern"}, {"text": "Strikte Autorität", "correct": false, "because": "Spannung erhöhen"}, {"text": "Passivität", "correct": false, "because": "Keine Lösung"}]');
